import http.serverimport socketserverimport osimport sysimport jsonimport subprocessimport threadingimport datetimeHOST = "10.10.10.10"PORT = 8384LOG_FILE = sys.argv[1] if len(sys.argv) > 1 else "log.txt"# ==========================================# SET YOUR PASSWORD HERE# ==========================================UPDATE_PASSWORD = "YOUR_PASSWORD_HERE"# ==========================================# CONFIGURE YOUR SERVICES AND DIRECTORIES HERE# ==========================================SERVICES = {    "Tailscale": "/home/bigbox/Documents/Homer/dockers/tailscale",    "AdGuard Home DNS": "/home/bigbox/Documents/Homer/dockers/adguard",    "Unbound DNS Resolver": "/home/bigbox/Documents/Homer/dockers/unbound",    "Nginx Proxy": "/home/bigbox/Documents/Homer/dockers/nginx",    "Duplicati": "/home/bigbox/Documents/Homer/dockers/duplicati",    "Cloud": "/home/bigbox/Documents/Homer/dockers/filebrowser",    "Seerr": "/home/bigbox/Documents/Homer/dockers/seer_source1",    "Prowlarr": "/home/bigbox/Documents/Homer/dockers/prowlarr_source1",    "Radarr": "/home/bigbox/Documents/Homer/dockers/radarr_source1",    "Sonarr": "/home/bigbox/Documents/Homer/dockers/sonarr_source1",    "Wizarr": "/home/bigbox/Documents/Homer/dockers/wizarr",    "Navidrome": "/home/bigbox/Documents/Homer/dockers/navidrome",    "Music Grabber": "/home/bigbox/Documents/Homer/dockers/musicgrabber",    "VueTorrent": "/home/bigbox/Documents/Homer/dockers/qbittorrent",    "Vaultwarden": "/home/bigbox/Documents/Homer/dockers/vaultwarden",    "SearXNG": "/home/bigbox/Documents/Homer/dockers/searxng",    "Portainer": "/home/bigbox/Documents/Homer/dockers/portainer",    "Speedtest": "/home/bigbox/Documents/Homer/dockers/speedtest-tracker",    "Stirling PDF": "/home/bigbox/Documents/Homer/dockers/stirling",    "OmniTools": "/home/bigbox/Documents/Homer/dockers/omni-tools",    "CyberChef": "/home/bigbox/Documents/Homer/dockers/cyberchef",    "ConvertX": "/home/bigbox/Documents/Homer/dockers/convertx",    "ngrok tunnel": "/home/bigbox/Documents/Homer/dockers/ngrok"}HTML_TEMPLATE = """<!DOCTYPE html><html lang="en"><head>    <meta charset="UTF-8">    <meta name="viewport" content="width=device-width, initial-scale=1.0">    <title>Maintenance</title>    <style>        body {            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;            background-color: #121212;             color: #ffffff;            margin: 0;            padding: 15px;             display: flex;            flex-direction: column;            align-items: center;            min-height: 100vh;            box-sizing: border-box;            overflow-x: hidden; /* Prevents body from scrolling horizontally */        }        .header-bar {            width: 100%;            max-width: 1200px;            display: flex;            justify-content: flex-start;            margin-bottom: 20px;        }        .update-btn {            background-color: #1a1a1a;            color: #eaeaea;            border: 2px solid #00d462;            padding: 10px 22px;            border-radius: 8px;            font-size: 15px;            font-weight: 600;            cursor: pointer;            transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;        }        .update-btn:hover {            background-color: #00d462;            color: #121212;            box-shadow: 0 0 12px rgba(0, 212, 98, 0.4);        }        .update-btn:active {            transform: scale(0.96);        }        .dashboard-container {            display: grid;            /* Auto-fill naturally adapts to mobile (1 col) and PC (multi-col) seamlessly */            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));             grid-gap: 15px;            width: 100%;            max-width: 1200px;            margin: 0 auto;        }        .service-card {            background-color: #1a1a1a;             border-radius: 8px; /* Smaller radius */            padding: 15px; /* Reduced padding to maximize screen space */            display: flex;            flex-direction: column;            justify-content: center;            box-shadow: 0 4px 6px rgba(0,0,0,0.3);            border: 2px solid transparent;             transition: transform 0.2s ease, box-shadow 0.2s ease, border 0.2s ease;            cursor: pointer;            overflow: hidden; /* Contains any wild overflowing text */        }        .service-card:hover {            transform: translateY(-3px);            box-shadow: 0 8px 15px rgba(0,0,0,0.5);        }        .service-card.selected {            border: 2px solid #00d462;            box-shadow: 0 0 15px rgba(0, 212, 98, 0.2);        }        .raw-data {            font-family: monospace; /* Monospace is much cleaner for server logs */            font-size: 0.85rem; /* Smaller font to fit long text */            font-weight: 500;            color: #eaeaea;            margin: 0;            line-height: 1.4;            word-break: break-word; /* Forces long strings to wrap */            overflow-wrap: break-word;            white-space: pre-wrap; /* Honors spaces but safely wraps new lines */        }        /* Modal Overlay & Sheet */        #modal-overlay {            position: fixed;            top: 0;            left: 0;            width: 100%;            height: 100%;            background: rgba(0,0,0,0.6);            backdrop-filter: blur(4px);            z-index: 998;            opacity: 0;            visibility: hidden;            transition: opacity 0.2s ease;        }        #modal-overlay.active {            opacity: 1;            visibility: visible;        }        #service-modal {            position: fixed;            top: 50%;            left: 50%;            transform: translate(-50%, -50%) scale(0.95);            background: #1a1a1a;            border: 1px solid #333;            border-radius: 14px;            padding: 22px;            width: 90%;            max-width: 420px;            z-index: 999;            opacity: 0;            visibility: hidden;            transition: all 0.2s ease;            box-shadow: 0 10px 30px rgba(0,0,0,0.6);            display: flex;            flex-direction: column;            gap: 10px;        }        #service-modal.active {            opacity: 1;            visibility: visible;            transform: translate(-50%, -50%) scale(1);        }        .modal-title {            font-size: 18px;            font-weight: bold;            color: #fff;            text-align: center;            margin-bottom: 5px;        }        .service-list {            display: flex;            flex-direction: column;            gap: 8px;            max-height: 320px;            overflow-y: auto;        }        .service-select-btn {            background: #252525;            color: #eaeaea;            border: 1px solid #383838;            padding: 12px 16px;            border-radius: 8px;            font-size: 14px;            font-weight: 600;            text-align: left;            cursor: pointer;            transition: background-color 0.2s, border-color 0.2s;        }        .service-select-btn:hover {            background: #333333;            border-color: #00d462;            color: #00d462;        }        .modal-cancel-btn {            background: transparent;            color: #ff4444;            border: none;            padding: 10px;            font-weight: bold;            cursor: pointer;            text-align: center;            border-radius: 6px;            margin-top: 5px;        }        .modal-cancel-btn:hover {            background: rgba(255, 68, 68, 0.1);        }    </style></head><body>    <div class="header-bar">        <button class="update-btn" onclick="openModal()">Update Services</button>    </div>    <div class="dashboard-container">        {content}    </div>    <!-- Selection Modal -->    <div id="modal-overlay" onclick="closeModal()"></div>    <div id="service-modal">        <div class="modal-title">Select Service to Update</div>        <div class="service-list">            {service_buttons}        </div>        <button class="modal-cancel-btn" onclick="closeModal()">Cancel</button>    </div>    <script>        document.addEventListener('DOMContentLoaded', () => {            const cards = document.querySelectorAll('.service-card');            cards.forEach(card => {                card.addEventListener('click', () => {                    cards.forEach(c => c.classList.remove('selected'));                    card.classList.add('selected');                });            });        });        function openModal() {            document.getElementById('modal-overlay').classList.add('active');            document.getElementById('service-modal').classList.add('active');        }        function closeModal() {            document.getElementById('modal-overlay').classList.remove('active');            document.getElementById('service-modal').classList.remove('active');        }        async function triggerUpdate(serviceName) {            // --- NEW: Ask for password ---            let pw = prompt(`Enter password to update ${serviceName}:`);            if (pw === null) return; // Stop if user pressed Cancel            // -----------------------------                        closeModal();            try {                const response = await fetch('/api/update', {                    method: 'POST',                    headers: { 'Content-Type': 'application/json' },                    // --- NEW: Send password to backend ---                    body: JSON.stringify({ service: serviceName, password: pw })                });                const result = await response.json();                                if (response.ok) {                    alert(`Update triggered for ${serviceName}! Check logs for output.`);                    setTimeout(() => window.location.reload(), 3000);                // --- NEW: Catch wrong password ---                } else if (response.status === 401) {                    alert(`Error: Incorrect Password!`);                // ---------------------------------                } else {                    alert(`Error: ${result.error || 'Update failed'}`);                }            } catch (err) {                alert('Network error communicating with server.');            }        }    </script></body></html>"""def run_background_update(target_dir, service_name):    """Executes the bash script and pipes output line-by-line with a uniform timestamp."""    abs_log_file = os.path.abspath(LOG_FILE)     try:        with open(abs_log_file, "a", encoding="utf-8") as f:            start_time = datetime.datetime.now().strftime("[%d-%m-%Y %H:%M]")            f.write(f"{start_time} Starting update: {service_name}\n")            f.flush()            # Use Popen to read the output line-by-line            process = subprocess.Popen(                ["bash", "update.sh"],                cwd=target_dir,                stdout=subprocess.PIPE,                stderr=subprocess.STDOUT,                text=True,                bufsize=1            )            # Prepend the timestamp to every line the bash script spits out            for line in process.stdout:                current_time = datetime.datetime.now().strftime("[%d-%m-%Y %H:%M]")                f.write(f"{current_time} {line}")                f.flush()            process.wait()                        end_time = datetime.datetime.now().strftime("[%d-%m-%Y %H:%M]")            if process.returncode == 0:                f.write(f"{end_time} Update complete: {service_name}\n")            else:                f.write(f"{end_time} Update failed: {service_name} (Exit code {process.returncode})\n")    except Exception as e:        with open(abs_log_file, "a", encoding="utf-8") as f:            err_time = datetime.datetime.now().strftime("[%d-%m-%Y %H:%M]")            f.write(f"{err_time} Unexpected Error: {service_name} ({e})\n")class DashboardHandler(http.server.BaseHTTPRequestHandler):    def do_POST(self):        if self.path == '/api/update':            try:                content_len = int(self.headers.get('Content-Length', 0))                data = json.loads(self.rfile.read(content_len).decode('utf-8'))                # --- NEW: PASSWORD CHECK ---                provided_password = data.get('password', '')                if provided_password != UPDATE_PASSWORD:                    self.send_response(401)                    self.send_header('Content-Type', 'application/json')                    self.end_headers()                    self.wfile.write(json.dumps({"error": "Unauthorized"}).encode('utf-8'))                    return                # ---------------------------                service_name = data.get('service')                target_dir = SERVICES.get(service_name)                if not target_dir:                    self.send_response(400)                    self.send_header('Content-Type', 'application/json')                    self.end_headers()                    self.wfile.write(json.dumps({"error": "Unknown service"}).encode('utf-8'))                    return                script_path = os.path.join(target_dir, "update.sh")                if not os.path.exists(script_path):                    self.send_response(404)                    self.send_header('Content-Type', 'application/json')                    self.end_headers()                    self.wfile.write(json.dumps({"error": f"update.sh not found in {target_dir}"}).encode('utf-8'))                    return                # Spawn a safe background thread to run the update and pipe logs                thread = threading.Thread(target=run_background_update, args=(target_dir, service_name))                thread.daemon = True  # Allows Python to exit even if this thread is running                thread.start()                self.send_response(200)                self.send_header('Content-Type', 'application/json')                self.end_headers()                self.wfile.write(json.dumps({"status": "started"}).encode('utf-8'))            except Exception as e:                self.send_response(500)                self.send_header('Content-Type', 'application/json')                self.end_headers()                self.wfile.write(json.dumps({"error": str(e)}).encode('utf-8'))        else:            self.send_error(404)    def do_GET(self):        if self.path == '/':            self.send_response(200)            self.send_header('Content-type', 'text/html')            self.end_headers()            cards_html = ""            if os.path.exists(LOG_FILE):                with open(LOG_FILE, 'r', encoding='utf-8') as f:                    lines = f.readlines()                    for index, line in enumerate(reversed(lines)):                        raw_text = line.strip()                        if raw_text:                            card_class = "service-card selected" if index == 0 else "service-card"                            cards_html += f"""                            <div class="{card_class}">                                <span class="raw-data">{raw_text}</span>                            </div>                            """            else:                cards_html = '<div class="service-card"><span class="raw-data">Waiting for log.txt...</span></div>'            service_buttons = ""            for name in SERVICES.keys():                service_buttons += f'<button class="service-select-btn" onclick="triggerUpdate(\'{name}\')">{name}</button>\n'            final_html = HTML_TEMPLATE.replace('{content}', cards_html).replace('{service_buttons}', service_buttons)            self.wfile.write(final_html.encode('utf-8'))        else:            self.send_error(404)if __name__ == "__main__":    with socketserver.TCPServer((HOST, PORT), DashboardHandler) as httpd:        print(f"Server started on port {PORT} using Python's built-in http.server")        print(f"View your Maintenance logs at: http://{HOST}:{PORT}")        print("Press Ctrl+C to stop.")        try:            httpd.serve_forever()        except KeyboardInterrupt:            print("\nShutting down server.")            httpd.server_close()